@using sv_3f41ab87dba9423e90353877bcad0b2a.Services

<div class="card h-100 product-card" @onclick="HandleCardClick" role="button">
    <div class="card-img-top bg-secondary d-flex align-items-center justify-content-center"
         style="height: 180px;"
         role="img"
         aria-label="@Product.Name">
        <span class="text-white text-center px-2">@Product.Name</span>
    </div>
    <div class="card-body d-flex flex-column">
        <h5 class="card-title">@Product.Name</h5>
        <p class="card-text fw-bold text-primary">@Product.Price.ToString("C")</p>
        <p class="card-text">
            @for (int i = 1; i <= 5; i++)
            {
                @(i <= (int)Math.Round(Product.Rating) ? "★" : "☆")
            }
        </p>
        @if (!Product.InStock)
        {
            <span class="badge bg-danger mb-2">Out of Stock</span>
        }
        <button class="btn btn-primary mt-auto"
                disabled="@(!Product.InStock)"
                @onclick="HandleAddToCart"
                @onclick:stopPropagation="true">
            Add to Cart
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public Product Product { get; set; } = default!;
    [Parameter] public EventCallback<Product> OnSelected { get; set; }
    [Parameter] public EventCallback<Product> OnAddToCart { get; set; }

    private async Task HandleCardClick() => await OnSelected.InvokeAsync(Product);
    private async Task HandleAddToCart() => await OnAddToCart.InvokeAsync(Product);
}

@using sv_3f41ab87dba9423e90353877bcad0b2a.Services

@if (Loading)
{
    <div class="d-flex justify-content-center py-5">
        <div class="spinner-border text-primary" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @ErrorMessage
    </div>
}
else if (Products is null || Products.Count == 0)
{
    <div class="alert alert-info" role="alert">
        No products found matching your criteria.
    </div>
}
else
{
    <div class="row row-cols-1 row-cols-md-2 row-cols-lg-3 g-4">
        @foreach (var product in Products)
        {
            <div class="col">
                <ProductCard Product="product"
                             OnSelected="OnProductSelected"
                             OnAddToCart="OnAddToCart" />
            </div>
        }
    </div>
}

@code {
    [Parameter] public List<Product>? Products { get; set; }
    [Parameter] public bool Loading { get; set; }
    [Parameter] public string? ErrorMessage { get; set; }
    [Parameter] public EventCallback<Product> OnProductSelected { get; set; }
    [Parameter] public EventCallback<Product> OnAddToCart { get; set; }
}

